   // Financial tail is separate from the retained11 native commands and29 cohort.
   // Account commands use actual HTTP; the control is read/export UI only.
   async function nativeBankHttp({query=null,body=null,key=null,expected=200,ackLost=false}){
    assert.ok(body===null||query===null);assert.equal(ackLost,!!(body&&expected===201));
    if(body){assert.match(key,/^[a-f0-9-]{36}$/i);assert.ok(['propose','approve','reject'].includes(body.command));}
    else assert.ok(query&&['bootstrap','detail','attempt'].includes(query.resource));
    const before=writes.length,requests=[],observe=request=>{const u=new URL(request.url());if(u.origin===origin&&u.pathname==='/api/internal-own-bank-accounts')requests.push(request);};page.on('request',observe);if(ackLost)drop=true;
    try{
    const packet=await page.evaluate(async input=>{const url='/api/internal-own-bank-accounts'+(input.query?'?'+new URLSearchParams(input.query):''),bodyText=input.body?JSON.stringify({operation:'command',payload:input.body}):null,response=await fetch(url,{method:input.body?'POST':'GET',cache:'no-store',credentials:'same-origin',headers:input.body?{'content-type':'application/json','idempotency-key':input.key}:{},...(bodyText?{body:bodyText}:{})}),text=await response.text();if(text.length>12*1024*1024)throw Error('QA_BANK_HTTP_RESPONSE_LIMIT');return{status:response.status,value:JSON.parse(text),bodyText};},{query,body,key});
    if(!ackLost){assert.equal(packet.status,expected,JSON.stringify(packet.value));assert.equal(packet.value.ok,expected<400);assert.equal(writes.length,before);assert.equal(requests.length,1);assert.equal(requests[0].method(),body?'POST':'GET');if(body){assert.deepEqual(requests[0].postDataJSON(),{operation:'command',payload:body});assert.equal((await requests[0].allHeaders())['idempotency-key'],key);}return {status:packet.status,data:packet.value.data??null,envelope:packet.value,actualHttp:true,sameServer:true,authenticationFixture:true};}
    assert.equal(packet.status,503);assert.equal(packet.value.ok,false);assert.equal(writes.length,before+1);
    const committed=writes.at(-1);assert.equal(committed.kind,'bankAccounts');assert.equal(committed.key,key);assert.equal(committed.status,201);assert.deepEqual(committed.receipt.body,body);assert.equal(committed.receipt.replayed,false);
    const recovered=await nativeBankHttp({query:{resource:'attempt',key}});assert.deepEqual(recovered.data,{...committed.receipt,replayed:true});
    const posts=requests.filter(r=>r.method()==='POST'),gets=requests.filter(r=>r.method()==='GET');assert.equal(requests.length,2);assert.equal(posts.length,1);assert.equal(gets.length,1);assert.deepEqual(posts[0].postDataJSON(),{operation:'command',payload:body});assert.equal((await posts[0].allHeaders())['idempotency-key'],key);assert.equal(new URL(gets[0].url()).searchParams.get('resource'),'attempt');assert.equal(new URL(gets[0].url()).searchParams.get('key'),key);
    return {status:201,data:committed.receipt,recovered:recovered.data,key,bodyText:packet.bodyText,postStatus:503,committedStatus:201,browserPosts:posts.length,recoveryGets:gets.length,ackLostAfterCommit:true,actualHttp:true,sameServer:true,authenticationFixture:true};
    }finally{page.off('request',observe);}
   }
